head -n -3 game.html > game.tmp && mv game.tmp game.html && cat >> game.html <<'CHUNK2'

/* ============================= WORKER EFFECTIVENESS ============================= */
function effOf(c,def){
  if(!c||c.refused)return 0;
  let e=(c.job===def.job)?(0.55+0.15*c.skill):0.45;
  e*=0.5+c.morale/200;
  if(c.fatigue>80)e*=0.6;
  return e;
}

/* ============================= BUILDING RUN / PREVIEW =============================
   apply=false gives a side-effect-free preview (used for tooltips and tests). */
function runBuilding(state,i,apply){
  const tile=state.map[i],b=tile.b,def=BUILD[b.k];
  const r={ins:{},outs:{},notes:[],active:false};
  if(def.slots===0){r.notes.push(def.desc);return r;}
  if(b.hp<=0){r.notes.push('DISABLED - repair needed');return r;}
  const hpMul=b.hp<50?0.5:1;
  if(hpMul<1)r.notes.push('damaged (HP '+b.hp+'): output halved');
  const glob=state.flags.ashfall>0?0.7:1;
  if(glob<1)r.notes.push('thick ashfall: -30% output');
  const w=workerOf(state,i);
  const eff=effOf(w,def);
  if(b.k!=='generator'&&b.k!=='habitat'){
    if(!w){r.notes.push('no worker assigned');return r;}
    if(eff===0){r.notes.push(w.name+' refuses to work (morale too low)');return r;}
    if(w.job!==def.job)r.notes.push(w.name+' works off-trade (0.45 eff, no skill growth)');
  }
  switch(b.k){
    case 'generator':{
      if(state.flags.ventShut>0){r.notes.push('vents shut this turn: no output');return r;}
      r.outs.power=(2+3*eff)*hpMul*glob;
      if(!w)r.notes.push('unmanned: base 2 power only');
      break;}
    case 'habitat':{
      r.notes.push('Steward on duty: faster rest + morale for everyone (scales with skill).');
      r.active=!!w&&eff>0;
      if(apply&&r.active)w.worked='light';
      return r;}
    case 'sifter':r.outs.soil=3.5*eff*hpMul*glob;break;
    case 'mine':r.outs.ore=4*eff*(hasR(state,'deepmine')?1.5:1)*hpMul*glob;
      if(hasR(state,'deepmine'))r.notes.push('Deep Mining: +50%');break;
    case 'scavenger':r.outs.ore=2*eff*hpMul*glob;r.outs.scrip=2*eff*hpMul*glob;
      r.notes.push('15% chance each turn: +1 parts');break;
    case 'condenser':{
      const aw=adjCount(state,i,'water');
      r.outs.water=(5*eff+2*aw)*(hasR(state,'condense2')?1.4:1)*hpMul*glob;
      if(aw>0)r.notes.push('adjacency: +'+(2*aw)+' water from '+aw+' adjacent water tile(s)');
      if(hasR(state,'condense2'))r.notes.push('Fog Nets: +40%');
      break;}
    case 'greenhouse':{
      const aw=adjCount(state,i,'water');
      r.ins.soil=2;r.ins.water=hasR(state,'drip')?1:2;
      r.outs.food=8*eff*(hasR(state,'ashAgri')?1.3:1)*(1+0.1*aw)*hpMul*glob;
      if(aw>0)r.notes.push('adjacency: +'+(aw*10)+'% food from '+aw+' adjacent water tile(s)');
      if(hasR(state,'ashAgri'))r.notes.push('Ash Agronomy: +30%');
      if(hasR(state,'drip'))r.notes.push('Drip Irrigation: water use halved');
      break;}
    case 'forge':{
      const av=adjCount(state,i,'vent');
      r.ins.ore=4;r.ins.power=av>0?1:2;
      r.outs.metal=3*eff*(hasR(state,'smelt')?1.34:1)*(av>0?1.25:1)*hpMul*glob;
      if(av>0)r.notes.push('adjacency: vent heat, power cost 1 (not 2) and +25% metal');
      if(hasR(state,'smelt'))r.notes.push('Smelting Efficiency: +34%');
      break;}
    case 'workshop':r.ins.metal=2;r.ins.power=1;r.outs.parts=2*eff*hpMul*glob;break;
  }
  let ratio=1;
  for(const k in r.ins)if(r.ins[k]>0)
    ratio=Math.min(ratio,Math.max(0,Math.min(1,state.res[k]/r.ins[k])));
  if(ratio<1)r.notes.push('inputs short: running at '+Math.round(ratio*100)+'%');
  for(const k in r.ins)r.ins[k]*=ratio;
  for(const k in r.outs)r.outs[k]*=ratio;
  r.active=ratio>0&&(Object.keys(r.outs).length>0);
  if(apply&&r.active){
    for(const k in r.ins)state.res[k]=Math.max(0,state.res[k]-r.ins[k]);
    for(const k in r.outs)state.res[k]+=r.outs[k];
    if(w&&eff>0)w.worked=true;
    if(b.k==='scavenger'&&rnd(state)<0.15){state.res.parts+=1;slog(state,'Scavengers turned up spare parts (+1).');}
  }
  return r;
}
const PRODORDER=['generator','sifter','mine','scavenger','condenser','forge','workshop','greenhouse','habitat'];

/* ============================= TURN PHASES ============================= */
function stormMitigation(state){
  let m=1;if(hasR(state,'forecast'))m*=0.7;if(hasR(state,'reinforce'))m*=0.7;return m;
}
function stormPhase(state){
  state.flags.stormWarn=hasR(state,'forecast')&&((state.turn+1)%8===0);
  if(state.turn%8!==0||state.turn===0){state.stormNow=false;return;}
  state.stormNow=true;
  const sev=1+Math.floor(state.turn/20);
  const mit=stormMitigation(state);
  let hits=0,disabled=0;
  for(let i=0;i<64;i++){
    const b=state.map[i].b;if(!b)continue;
    if(rnd(state)<0.6){
      let dmg=(8+6*sev+ri(state,8))*mit;
      const walled=b.k!=='wall'&&adjTiles(i).some(j=>{
        const nb=state.map[j].b;return nb&&nb.k==='wall'&&nb.hp>0;});
      if(walled)dmg*=0.5;
      dmg=Math.round(dmg);
      const was=b.hp;b.hp=Math.max(0,b.hp-dmg);hits++;
      if(b.hp<=0&&was>0){disabled++;slog(state,BUILD[b.k].name+' at '+tileLabel(i)+' was DISABLED by the storm.');}
    }
  }
  slog(state,'ASHSTORM (severity '+sev+')! '+hits+' building(s) damaged'+
    (disabled?', '+disabled+' disabled':'')+'. Water use x1.5 this turn.'+
    (mit<1?' (Mitigation research reduced damage to '+Math.round(mit*100)+'%.)':''));
}
function productionPhase(state){
  for(const c of state.colonists)c.worked=false;
  for(const k of PRODORDER)
    for(let i=0;i<64;i++){
      const b=state.map[i].b;
      if(b&&b.k===k)runBuilding(state,i,true);
    }
  state.flags.ashfall=Math.max(0,state.flags.ashfall-1);
  state.flags.ventShut=Math.max(0,state.flags.ventShut-1);
}
function needsPhase(state){
  const pop=state.colonists.length;
  const fNeed=pop,wNeed=pop*(state.stormNow?1.5:1);
  const fShort=Math.max(0,fNeed-state.res.food),wShort=Math.max(0,wNeed-state.res.water);
  state.res.food=Math.max(0,state.res.food-fNeed);
  state.res.water=Math.max(0,state.res.water-wNeed);
  state.short={f:fShort>0.001,w:wShort>0.001};
  if(state.short.f)slog(state,'FOOD SHORTAGE: '+fmt(fShort)+' meals missing. Morale is falling.');
  if(state.short.w)slog(state,'WATER SHORTAGE: '+fmt(wShort)+' rations missing. Morale is falling.');
}
function peoplePhase(state){
  let stew=0;
  for(let i=0;i<64;i++){
    const b=state.map[i].b;
    if(b&&b.k==='habitat'&&b.hp>0){
      const w=workerOf(state,i);
      if(w&&!w.refused)stew+=1+w.skill*0.5;
    }
  }
  const recBase=hasR(state,'medicine')?30:20;
  for(const c of state.colonists){
    if(c.worked===true)c.fatigue=Math.min(100,c.fatigue+12);
    else if(c.worked==='light')c.fatigue=Math.min(100,c.fatigue+6);
    else c.fatigue=Math.max(0,c.fatigue-(recBase+stew));
    let dm=0;
    if(state.short.f)dm-=12;
    if(state.short.w)dm-=12;
    if(!state.short.f&&!state.short.w&&state.res.food>0&&state.res.water>0)dm+=3;
    if(c.fatigue>85)dm-=4;
    dm+=Math.min(3,stew*0.5);
    c.morale=Math.max(0,Math.min(100,c.morale+dm));
    if(c.worked===true&&c.at!=null){
      const b=state.map[c.at].b;
      if(b&&BUILD[b.k].job===c.job){
        c.xp=(c.xp||0)+1;
        if(c.xp>=c.skill*6&&c.skill<5){c.skill++;c.xp=0;
          slog(state,c.name+' has grown more skilled ('+c.job+' '+c.skill+'/5).');}
      }
    }
    c.refused=c.morale<15;
    c.worked=false;
  }
  for(const c of state.colonists.slice()){
    if(c.morale<=0&&rnd(state)<0.3){
      state.colonists=state.colonists.filter(x=>x!==c);
      slog(state,c.name+' walked into the ash and did not come back. ('+state.colonists.length+' remain)');
    }
  }
  const cap=popCap(state),pop=state.colonists.length;
  if(pop>0&&pop<cap&&state.res.food>pop*1.5&&state.res.water>pop*1.5&&avgMorale(state)>=55){
    const p=0.12+(hasR(state,'beacon')?0.15:0);
    if(rnd(state)<p){
      const c=newColonist(state,JOBS[ri(state,4)],1+ri(state,2));
      state.colonists.push(c);
      slog(state,c.name+' ('+c.job+') heard of the outpost and joined. Population '+state.colonists.length+'/'+cap+'.');
    }
  }
}
function marketPhase(state){
  const m=state.market;
  for(const g of GOODS)m.drift[g]=Math.min(2,Math.max(0.5,m.drift[g]*(0.97+rnd(state)*0.06)));
  if(m.here&&state.turn>=m.leaveTurn){
    m.here=false;state.flags.tradeDiscount=0;
    m.nextArrive=state.turn+5+ri(state,4);
    slog(state,'The caravan packs up and departs.');
  }
  if(!m.here&&state.turn>=m.nextArrive){
    m.here=true;m.leaveTurn=state.turn+(hasR(state,'trade')?3:2);
    m.inv={food:10+ri(state,15),water:10+ri(state,15),metal:5+ri(state,10),
      parts:2+ri(state,6),ore:8+ri(state,10)};
    m.scrip=50+state.turn+ri(state,30);
    slog(state,'A trade caravan has arrived (stays through turn '+m.leaveTurn+').');
  }
}
function capsPhase(state){
  for(const r of RES){
    if(state.res[r]<0)state.res[r]=0;
    const cap=capFor(state,r);
    if(state.res[r]>cap){
      const lost=state.res[r]-cap;
      state.res[r]=cap;
      slog(state,'Overflow: '+fmt(lost)+' '+r+' lost (storage cap '+cap+').');
    }
  }
}
function endCheck(state){
  if(state.colonists.length===0){
    if(!state.over)slog(state,'The outpost stands empty. The ash takes the rest.');
    state.over={won:false,turn:state.turn};
    return;
  }
  if(state.turn>=60&&!state.wonShown&&state.colonists.length>=12&&
     !state.short.f&&!state.short.w&&state.res.food>0&&state.res.water>0){
    state.wonShown=true;state.over={won:true,turn:state.turn};
    slog(state,'VICTORY: the outpost stands at turn '+state.turn+' with '+state.colonists.length+' souls, fed and watered.');
  }
}
function simTurn(state){
  if(state.pending)return;
  if(state.over&&!state.over.won)return;
  state.turn++;
  stormPhase(state);
  productionPhase(state);
  needsPhase(state);
  peoplePhase(state);
  marketPhase(state);
  eventsPhase(state);
  capsPhase(state);
  endCheck(state);
}
function scoreOf(state){
  const r=state.res;
  const stock=Math.floor((r.food+r.water+r.metal+r.ore+r.soil+2*r.parts+0.5*r.scrip)/5);
  return {pop:state.colonists.length*15,research:state.research.done.length*20,
    stock:stock,turns:state.turn*2,win:state.wonShown?200:0,
    total:state.colonists.length*15+state.research.done.length*20+stock+state.turn*2+(state.wonShown?200:0)};
}

/* ============================= PLAYER ACTIONS ============================= */
function canBuild(state,i,k){
  const def=BUILD[k],tile=state.map[i];
  if(tile.b)return{ok:false,r:'tile occupied'};
  if(def.terrain.indexOf(tile.t)<0)return{ok:false,r:'needs '+def.terrain.join(' or ')+' terrain'};
  if(def.needsR&&!hasR(state,def.needsR))return{ok:false,r:'requires research: '+RESEARCH[def.needsR].name};
  for(const res in def.cost)if(state.res[res]<def.cost[res])
    return{ok:false,r:'need '+def.cost[res]+' '+res};
  return{ok:true};
}
function doBuild(state,i,k){
  const c=canBuild(state,i,k);if(!c.ok)return c;
  for(const res in BUILD[k].cost)state.res[res]-=BUILD[k].cost[res];
  state.map[i].b={k:k,hp:100};
  slog(state,'Built '+BUILD[k].name+' at '+tileLabel(i)+'.');
  return{ok:true};
}
function doDemolish(state,i){
  const b=state.map[i].b;if(!b)return;
  for(const c of state.colonists)if(c.at===i)c.at=null;
  const refund=Math.floor((BUILD[b.k].cost.metal||0)/2);
  give(state,'metal',refund);
  slog(state,'Demolished '+BUILD[b.k].name+' at '+tileLabel(i)+' (+'+refund+' metal salvage).');
  state.map[i].b=null;
}
function repairCost(b){return Math.ceil((100-b.hp)/20);}
function canRepair(state,i){
  const b=state.map[i].b;
  if(!b||b.hp>=100)return{ok:false,r:'nothing to repair'};
  const cost=repairCost(b);
  if(state.res.parts<cost)return{ok:false,r:'need '+cost+' parts'};
  const idle=state.colonists.filter(c=>c.at==null&&!c.refused)
    .sort((a,b2)=>a.fatigue-b2.fatigue||a.id-b2.id)[0];
  if(!idle)return{ok:false,r:'needs one idle (unassigned) colonist for the labor'};
  return{ok:true,cost:cost,idle:idle};
}
function doRepair(state,i){
  const c=canRepair(state,i);if(!c.ok)return c;
  state.res.parts-=c.cost;
  c.idle.fatigue=Math.min(100,c.idle.fatigue+15);
  state.map[i].b.hp=100;
  slog(state,c.idle.name+' repaired the '+BUILD[state.map[i].b.k].name+' at '+tileLabel(i)+' (-'+c.cost+' parts, +15 fatigue).');
  return{ok:true};
}
function buyResearch(state,id){
  const n=RESEARCH[id];
  if(!n)return{ok:false,r:'unknown research'};
  if(hasR(state,id))return{ok:false,r:'already researched'};
  for(const q of n.req)if(!hasR(state,q))return{ok:false,r:'requires '+RESEARCH[q].name};
  if(state.res.scrip<n.cost.scrip)return{ok:false,r:'need '+n.cost.scrip+' scrip'};
  if(state.res.parts<(n.cost.parts||0))return{ok:false,r:'need '+n.cost.parts+' parts'};
  state.res.scrip-=n.cost.scrip;state.res.parts-=n.cost.parts||0;
  state.research.done.push(id);
  slog(state,'Research complete: '+n.name+' - '+n.desc);
  return{ok:true};
}
function assign(state,cid,ti){
  const c=state.colonists.find(x=>x.id===cid);if(!c)return{ok:false,r:'no such colonist'};
  if(ti==null){c.at=null;return{ok:true};}
  const b=state.map[ti].b;if(!b)return{ok:false,r:'no building there'};
  const def=BUILD[b.k];
  if(!def.slots)return{ok:false,r:'no work slots there'};
  const used=state.colonists.filter(x=>x.at===ti&&x!==c).length;
  if(used>=def.slots)return{ok:false,r:'slot already filled'};
  c.at=ti;return{ok:true};
}

/* ============================= TRADE ============================= */
function priceOf(state,g){
  const cap=capFor(state,g);
  const sc=Math.min(1.5,Math.max(0.6,1.5-state.res[g]/cap));
  return BASE_PRICE[g]*state.market.drift[g]*sc;
}
function buyPriceOf(state,g){
  let p=priceOf(state,g)*(hasR(state,'trade')?1.15:1.3);
  if(state.flags.tradeDiscount)p*=0.85;
  return Math.max(1,Math.ceil(p));
}
function sellPriceOf(state,g){
  return Math.max(1,Math.floor(priceOf(state,g)*(hasR(state,'trade')?0.85:0.75)));
}
function doBuy(state,g,q){
  const m=state.market;if(!m.here)return{ok:false,r:'no caravan present'};
  const bp=buyPriceOf(state,g);
  const space=Math.max(0,Math.floor(capFor(state,g)-state.res[g]));
  q=Math.min(q,m.inv[g]||0,Math.floor(state.res.scrip/bp),space);
  if(q<=0)return{ok:false,r:'cannot buy (check scrip, caravan stock, storage space)'};
  m.inv[g]-=q;state.res[g]+=q;state.res.scrip-=q*bp;m.scrip+=q*bp;
  slog(state,'Bought '+q+' '+g+' for '+(q*bp)+' scrip.');
  return{ok:true};
}
function doSell(state,g,q){
  const m=state.market;if(!m.here)return{ok:false,r:'no caravan present'};
  const sp=sellPriceOf(state,g);
  q=Math.min(q,Math.floor(state.res[g]),Math.floor(m.scrip/sp));
  if(q<=0)return{ok:false,r:'cannot sell (check your stock and caravan scrip)'};
  state.res[g]-=q;state.res.scrip+=q*sp;m.scrip-=q*sp;m.inv[g]=(m.inv[g]||0)+q;
  slog(state,'Sold '+q+' '+g+' for '+(q*sp)+' scrip.');
  return{ok:true};
}
CHUNK2
echo "chunk2 appended, lines: $(wc -l < game.html)"

